#!/usr/bin/env python3
import sys
import rclpy
from rclpy.node import Node

from .srv import ChangeId, ChangeBaud
from .hand_driver import MPD20Driver


class DexHandConfigNode(Node):
    def __init__(self):
        super().__init__("dex_hand_config_node")

        # 1. 声明参数（带默认值）
        self.declare_parameter("serial_port", "/dev/ttyUSB0")
        self.declare_parameter("baudrate", 115200)

        # 2. 安全获取参数
        port = self.get_parameter("serial_port").get_parameter_value().string_value
        baudrate = self.get_parameter("baudrate").get_parameter_value().integer_value

        # 3. 初始化驱动
        self.driver = MPD20Driver(port=port, baudrate=baudrate)
        self.ready = False
        if not self.driver.connect():
            self.get_logger().error(f"配置节点串口连接失败：{port}")
            # 连接失败则抛出异常，让上层决定退出
            raise RuntimeError(f"无法打开串口 {port}")
        else:
            self.get_logger().info(f"配置节点连接成功：{port}（波特率：{baudrate})")
            self.ready = True

        # 4. 注册自定义服务（使用正确的服务类型）
        self.change_id_srv = self.create_service(
            ChangeId, "/dex_hand/change_id", self.change_id_callback
        )
        self.change_baud_srv = self.create_service(
            ChangeBaud, "/dex_hand/change_baud", self.change_baud_callback
        )

    def change_id_callback(self, request, response):
        """修改电机ID: 请求字段 command 格式为 "old_id>new_id" """
        if not self.ready:
            response.success = False
            response.message = "配置节点未就绪（驱动未连接）"
            return response

        try:
            # 增强解析：只允许恰好一个 '>'
            parts = request.command.strip().split('>')
            if len(parts) != 2:
                raise ValueError("需要严格一个 '>'")
            old_id, new_id = map(int, parts)

            if not (1 <= old_id <= 255 and 1 <= new_id <= 255):
                response.success = False
                response.message = "ID必须是1-255之间的整数"
                return response

            if self.driver.change_id(old_id, new_id):
                response.success = True
                response.message = f"电机ID修改指令已发送:{old_id} → {new_id}（需重启电机生效）"
            else:
                response.success = False
                response.message = "电机ID修改失败(检查电机是否在线)"
        except ValueError:
            response.success = False
            response.message = "参数格式错误! 需传入: old_id>new_id (例如 1>2)"
        except Exception as e:
            response.success = False
            response.message = f"修改ID失败: {str(e)}"
        return response

    def change_baud_callback(self, request, response):
        """修改电机波特率: 请求字段 command 格式为 "target_id>new_baud" """
        if not self.ready:
            response.success = False
            response.message = "配置节点未就绪（驱动未连接）"
            return response

        try:
            parts = request.command.strip().split('>')
            if len(parts) != 2:
                raise ValueError("需要严格一个 '>'")
            target_id, new_baud = map(int, parts)

            if not 1 <= target_id <= 255:
                response.success = False
                response.message = "电机ID必须是1-255之间的整数"
                return response

            if self.driver.change_baudrate(target_id, new_baud):
                response.success = True
                response.message = f"波特率修改指令已发送: ID={target_id} → {new_baud}（需重启电机生效）"
            else:
                supported = list(self.driver.BAUD_MAP.keys()) if hasattr(self.driver, 'BAUD_MAP') else "未知"
                response.success = False
                response.message = f"波特率修改失败（支持的波特率：{supported})"
        except ValueError:
            response.success = False
            response.message = "参数格式错误! 需传入: target_id>new_baud (例如 1>115200)"
        except Exception as e:
            response.success = False
            response.message = f"修改波特率失败: {str(e)}"
        return response

    def destroy_node(self):
        if hasattr(self, 'driver') and self.driver:
            try:
                self.driver.disconnect()
                self.get_logger().info("配置节点串口已断开")
            except Exception as e:
                self.get_logger().warn(f"断开串口时异常: {e}")
        super().destroy_node()


def main(args=None):
    rclpy.init(args=args)
    node = None
    try:
        node = DexHandConfigNode()
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    except Exception as e:
        print(f"节点启动失败: {e}", file=sys.stderr)
    finally:
        if node is not None:
            node.destroy_node()
        rclpy.shutdown()


if __name__ == "__main__":
    main()